      "content": "{\n  \"name\": \"dsh-cache-bricks\",\n  \"version\": \"0.1.5\",\n  \"description\": \"DSH web plugin: cache hit rate as falling Tetris-style bricks in the blank gutter beside the conversation — one brick per real model request attempt, one column per task, amber below 90% and red below 70%.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/invariant.js\",\n    \"lib/types/**/*.d.ts\",\n    \"src\",\n    \"scripts\",\n    \"cordis.patch.yml\",\n    \"docs\",\n    \"README.md\",\n    \"LICENSE\",\n    \"tests/clickfix.fixture.js\"\n  ],\n  \"scripts\": {\n    \"build\": \"rimraf lib && tsc -p tsconfig.build.json && tsdown\",\n    \"build:fast\": \"tsdown\",\n    \"build:hotfix\": \"node scripts/build-client-hotfix.mjs\",\n    \"check:contracts\": \"node scripts/check-contract-drift.mjs\",\n    \"typecheck\": \"tsc --noEmit -p tsconfig.json\",\n    \"test\": \"vitest run\",\n    \"test:watch\": \"vitest\",\n    \"test:clickfix\": \"node scripts/test-clickfix.mjs\",\n    \"test:scroll\": \"node scripts/test-scroll.mjs\",\n    \"verify:host\": \"node scripts/verify-host-artifact.mjs\",\n    \"verify:live\": \"node scripts/live-verify.mjs\",\n    \"verify:ui\": \"node scripts/ui-verify.mjs\",\n    \"pack:latest\": \"pnpm pack && node scripts/pack-latest.mjs\",\n    \"bench\": \"node -e \\\"process.env.DSH_BENCH='1'\\\" && vitest run tests/collector-cost.spec.ts\",\n    \"verify:live-scene\": \"node scripts/live-scene-verify.mjs\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-chat\"\n      ]\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-ui-chat\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"*\",\n    \"react\": \"^18.0.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.4\",\n    \"@deepseek-ai/dsh-client-ui-chat\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.1.7-rc.2\",\n    \"@types/react\": \"^18.3.1\",\n    \"@types/react-dom\": \"^18.3.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"rimraf\": \"^5.0.5\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^5.6.0\",\n    \"vitest\": \"^3.0.0\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/3289192-bot/dsh-cache-bricks.git\"\n  },\n  \"homepage\": \"https://github.com/3289192-bot/dsh-cache-bricks#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/3289192-bot/dsh-cache-bricks/issues\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"prompt-cache\"\n  ],\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-ui-chat\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-conversation\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-renderer\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    }\n  }\n}\n"
