      "path": "src/host/collect.ts",
      "content": "/**\n * The host half's collector: a read-only tap on the model-call path plus the\n * ledger and HTTP surface behind it.\n *\n * The whole design rests on one promise: **observing a request must not change\n * it**. DSH makes that easy to keep, and hard to break silently:\n *\n * - `llm/stream` is a waterfall, so its listener *is* the dispatch: the value it\n *   returns is the stream the agent loop consumes. Every path through this module\n *   returns `next()` — a listener that returns nothing would replace the model's\n *   stream with `undefined`.\n * - A loop-built request arrives deep-frozen, so writing to it throws rather than\n *   corrupting the prompt; this module only reads.\n * - Observation happens inside `try`/`catch`: a bug in the ledger must never turn\n *   into a failed model call.\n *\n * Attempt identity is the other half of the design. `llm/stream` carries the\n * request but no turn/step/attempt id; `agent/assistant-stream` carries the\n * identity but no request. The ledger pairs them through a per-session FIFO, so\n * whichever channel reports first, the two meet.\n */\nimport { BrickLedger, type Observation } from '../core/brick-ledger'\nimport { BlobStore } from '../core/blob-store'\nimport { createCacheBricksRouter } from './routes'\nimport {\n  RequestSummarizer,\n  chunkObservation,\n  compactionObservation,\n  contextObservation,\n  headerObservation,\n  retryObservation,\n  settlementObservation,\n  toolCallObservation,\n  toolResultObservation,\n  type ChunkLike,\n  type RequestLike,\n} from '../core/observe'\nimport type { BrickFeed } from '../shared/brick'\n\n/** Structural view of the Cordis context this plugin uses. */\nexport interface HostContextLike {\n  on(name: string, listener: (...args: never[]) => unknown, options?: { global?: boolean; prepend?: boolean }): unknown\n  get(name: string): unknown\n  inject(names: readonly string[], callback: (ctx: HostContextLike) => void): unknown\n  effect(callback: () => void | (() => void)): unknown\n}\n\n/** One session's observation state. */\ninterface SessionState {\n  readonly ledger: BrickLedger\n  readonly summarizer: RequestSummarizer\n  readonly listeners: Set<(feed: BrickFeed) => void>\n  /** True once the first dropped observation has been reported for this session. */\n  warnedUnattributed: boolean\n}\n\n/** Session lookup surface, as `@deepseek-ai/dsh-session` provides it. */\ninterface SessionsLike {\n  get(id: string): unknown\n}\n\n/** Token meter surface, as `@deepseek-ai/dsh-token-meter` provides it. */\ninterface TokenMeterLike {\n  measure(session: unknown, header?: unknown): {\n    readonly baseline?: { readonly kind?: string; readonly tokens?: number }\n    readonly surfaceDeltaTokens?: number\n    readonly totalTokens?: number\n    readonly surfaceTokens?: number\n    readonly nodes?: readonly unknown[]\n  }\n}\n\n/** Projection surface, as `@deepseek-ai/dsh-session-projection` provides it. */\ninterface ProjectionsLike {\n  stateOf(session: unknown, key: string): unknown\n}\n\n/** Options for {@link installCollector}. */\nexport interface CollectorOptions {\n  /** Bricks kept per session in memory. */\n  readonly maxBricks?: number\n  /** Session states kept before the least recently used is dropped. */\n  readonly maxSessions?: number\n  /** Bytes kept per session in the blob store. */\n  readonly maxStoreBytes?: number\n  /** Route namespace base path. */\n  readonly basePath?: string\n  /** Disable the HTTP surface (used by tests). */\n  readonly serve?: boolean\n}\n\n/** The collector handle, exposed so a host can inspect what was gathered. */\nexport interface Collector {\n  readonly store: BlobStore\n  feed(sessionId: string): BrickFeed | undefined\n  sessions(): readonly string[]\n  blob(ref: string): unknown\n  subscribe(sessionId: string, sink: (feed: BrickFeed) => void): () => void\n  dispose(): void\n}\n\n/**\n * Install the collector on a host context.\n * @param ctx - the plugin's Cordis context.\n * @param options - capacity and serving options.\n * @returns the collector, so tests and hosts can read from it directly.\n */\nexport function installCollector(ctx: HostContextLike, options: CollectorOptions = {}): Collector {\n  const store = new BlobStore({ maxTotalBytes: options.maxStoreBytes ?? 48 * 1024 * 1024 })\n  const sessions = new Map<string, SessionState>()\n  let disposed = false\n\n  /** Run an observation without ever letting it reach the caller. */\n  const safely = (action: () => void): void => {\n    try {\n      action()\n    } catch (error) {\n      // Never rethrow: this code sits inside the model-call path.\n      console.warn('[dsh-cache-bricks] observation failed:', error instanceof Error ? error.message : error)\n    }\n  }\n\n  /**\n   * Session states, capped. A long-running host sees many sessions, and each one\n   * holds a ledger and (through the shared store) raw payloads; the oldest is\n   * dropped rather than kept until the plugin is disposed.\n   */\n  const MAX_SESSIONS = options.maxSessions ?? 8\n\n  const stateFor = (sessionId: string): SessionState => {\n    const existing = sessions.get(sessionId)\n    if (existing !== undefined) {\n      // Re-insert to mark it as most recently used.\n      sessions.delete(sessionId)\n      sessions.set(sessionId, existing)\n      return existing\n    }\n    if (sessions.size >= MAX_SESSIONS) {\n      const oldest = sessions.keys().next()\n      if (oldest.done !== true) sessions.delete(oldest.value)\n    }\n    const state: SessionState = {\n      ledger: new BrickLedger(sessionId, {\n        store,\n        ...(options.maxBricks === undefined ? {} : { maxBricks: options.maxBricks }),\n      }),\n      summarizer: new RequestSummarizer(store),\n      listeners: new Set(),\n      warnedUnattributed: false,\n    }\n    sessions.set(sessionId, state)\n    return state\n  }\n\n  const PUBLISH_INTERVAL_MS = 100\n  let lastPublish = 0\n  let trailing: ReturnType<typeof setTimeout> | undefined\n\n  const publishNow = (state: SessionState): void => {\n    lastPublish = Date.now()\n    // Materializing every brick is the expensive part; skip it when the tab that\n    // asked for the stream has gone.\n    if (state.listeners.size === 0) return\n    const feed = state.ledger.feed()\n    for (const listener of state.listeners) {\n      try {\n        listener(feed)\n      } catch {\n        // A dead SSE client is not the collector's problem.\n      }\n    }\n  }\n\n  /**\n   * Push the current feed, coalesced to at most one send per\n   * {@link PUBLISH_INTERVAL_MS}. The trailing send matters: the last observation\n   * of an attempt must reach the browser even if it lands inside a quiet window.\n   */\n  const publish = (state: SessionState): void => {\n    const wait = PUBLISH_INTERVAL_MS - (Date.now() - lastPublish)\n    if (wait <= 0) {\n      publishNow(state)\n      return\n    }\n    if (trailing !== undefined) return\n    trailing = setTimeout(() => {\n      trailing = undefined\n      publishNow(state)\n    }, wait)\n  }\n\n  /**\n   * Observations worth waking a browser for.\n   *\n   * `agent/assistant-stream` emits one frame per token-level delta, and materializing\n   * every retained brick (up to 400) plus serializing the whole feed on each of a\n   * long answer's ~1500 chunks is pure waste: nothing a brick displays changes\n   * until usage, a tool call, or the attempt ends. Text and reasoning deltas are\n   * still folded — they just do not trigger a push.\n   */\n  const publishable = (observation: Observation): boolean => {\n    if (observation.kind === 'chunk') {\n      const type = observation.chunk.type\n      return type === 'usage' || type === 'finish' || type === 'tool-call'\n    }\n    return true\n  }\n\n  const collect = (sessionId: string, observation: Observation): void => {\n    const state = stateFor(sessionId)\n    state.ledger.observe(observation)\n    // A dropped observation is a hole in the record. Say so once per session rather than\n    // every time, and never paper over it by attaching it to an unrelated attempt.\n    if (!state.warnedUnattributed && state.ledger.unattributedCount > 0) {\n      state.warnedUnattributed = true\n      console.warn(\n        `[dsh-cache-bricks] dropped ${String(state.ledger.unattributedCount)} observation(s) for session `\n        + `${sessionId}: no attempt could be identified for them (see feed.unattributed).`,\n      )\n    }\n    if (state.listeners.size === 0) return\n    if (!publishable(observation)) return\n    publish(state)\n  }\n\n  /** Snapshot the context environment at dispatch: pressure, composition, meter. */\n  const snapshotContext = (sessionId: string): void => {\n    const session = (ctx.get('sessions') as SessionsLike | undefined)?.get(sessionId)\n    if (session === undefined) return\n    const pressure = (ctx.get('sessionProjections') as ProjectionsLike | undefined)?.stateOf(session, 'contextPressure') as\n      | { contextWindow?: number; pressureTokens?: number; surfaceTokens?: number; sampledSurfaceTokens?: number }\n      | undefined\n    const breakdown = (ctx.get('sessionProjections') as ProjectionsLike | undefined)?.stateOf(session, 'contextBreakdown') as\n      | { systemTokens?: number; toolsTokens?: number; messageTokens?: number }\n      | undefined\n    const header = (session as { requestHeader?: () => unknown }).requestHeader?.()\n    const meter = (ctx.get('tokenMeter') as TokenMeterLike | undefined)?.measure(session, header)\n    const meterRef = meter === undefined ? undefined : store.put(meter)\n    const projected = pressure?.pressureTokens !== undefined && pressure.surfaceTokens !== undefined\n      && pressure.sampledSurfaceTokens !== undefined\n      ? Math.max(0, pressure.pressureTokens + pressure.surfaceTokens - pressure.sampledSurfaceTokens)\n      : undefined\n    collect(sessionId, {\n      kind: 'pressure',\n      snapshot: {\n        ...(pressure?.contextWindow === undefined ? {} : { contextWindow: pressure.contextWindow }),\n        ...(pressure?.pressureTokens === undefined ? {} : { pressureTokens: pressure.pressureTokens }),\n        ...(projected === undefined ? {} : { projectedTokens: projected }),\n        ...(pressure?.surfaceTokens === undefined ? {} : { surfaceTokens: pressure.surfaceTokens }),\n        ...(breakdown?.systemTokens === undefined ? {} : { systemTokens: breakdown.systemTokens }),\n        ...(breakdown?.toolsTokens === undefined ? {} : { toolsTokens: breakdown.toolsTokens }),\n        ...(breakdown?.messageTokens === undefined ? {} : { messageTokens: breakdown.messageTokens }),\n        ...(meter?.baseline?.kind === undefined\n          ? {}\n          : { baselineKind: meter.baseline.kind as 'none' | 'estimated' | 'usage' }),\n        ...(meter?.baseline?.tokens === undefined ? {} : { baselineTokens: meter.baseline.tokens }),\n        ...(meter?.surfaceDeltaTokens === undefined ? {} : { surfaceDeltaTokens: meter.surfaceDeltaTokens }),\n        ...(meter?.totalTokens === undefined ? {} : { totalMeterTokens: meter.totalTokens }),\n        ...(meter?.nodes === undefined ? {} : { nodeCount: meter.nodes.length }),\n        ...(meterRef === undefined ? {} : { meterRef: meterRef.hash }),\n      },\n    })\n  }\n\n  // --- The model-call tap -------------------------------------------------\n  // `prepend` so the request is captured before any listener that might wrap or\n  // short-circuit the dispatch; `next()` is returned untouched, always.\n  ctx.on('llm/stream', ((...args: unknown[]) => {\n    const options = args[0] as RequestLike\n    const next = args[1] as () => unknown\n    // Every read of the payload is guarded: a hostile or exotic request object\n    // must not be able to turn into a throw inside the model-call path.\n    let sessionId = 'unknown'\n    try {\n      if (typeof options.sessionId === 'string') sessionId = options.sessionId\n    } catch {\n      sessionId = 'unknown'\n    }\n    safely(() => {\n      snapshotContext(sessionId)\n      collect(sessionId, { kind: 'dispatch', at: Date.now(), options: stateFor(sessionId).summarizer.summarize(options) })\n    })\n    const stream = next()\n    // Reading the payload is itself guarded: this code sits inside the model-call\n    // path, so even a hostile or exotic request object must not turn into a throw\n    // here. Anything unreadable is treated as a normal request.\n    let purpose: unknown\n    try {\n      purpose = options.purpose\n    } catch {\n      purpose = undefined\n    }\n    // An auxiliary call has no Turn attempt to pair with and produces no\n    // `agent/assistant-stream` frames, so its chunks can only be observed by\n    // wrapping the stream. The wrapper yields exactly what it receives: the\n    // request and the stream the caller consumes are both unchanged.\n    if (purpose !== 'compaction' && purpose !== 'session-title') return stream\n    return observeAuxiliary(stream, sessionId)\n  }) as (...args: never[]) => unknown, { global: true, prepend: true })\n\n  /**\n   * Pass every chunk through untouched while folding it onto the auxiliary brick.\n   * @param stream - the downstream async iterable.\n   * @param sessionId - the session the call belongs to.\n   * @returns an iterable that yields the same chunks in the same order.\n   */\n  async function* observeAuxiliary(stream: unknown, sessionId: string): AsyncGenerator<unknown> {\n    try {\n      for await (const chunk of stream as AsyncIterable<unknown>) {\n        safely(() => {\n          collect(sessionId, {\n            kind: 'chunk',\n            at: Date.now(),\n            chunk: chunkObservation(chunk as ChunkLike),\n            auxiliary: true,\n          })\n        })\n        yield chunk\n      }\n    } finally {\n      safely(() => {\n        collect(sessionId, { kind: 'attempt-end', at: Date.now(), outcome: 'committed', auxiliary: true })\n      })\n    }\n  }\n\n  // --- Live attempt frames ------------------------------------------------\n  ctx.on('agent/assistant-stream', ((...args: unknown[]) => {\n    const payload = args[0] as {\n      agent?: { session?: { id?: string } }\n      frame?: {\n        type?: string\n        attemptId?: string\n        revision?: number\n        turn?: number\n        step?: number\n        time?: number\n        chunk?: ChunkLike\n        outcome?: { kind?: string; eventType?: string; seq?: number }\n      }\n    }\n    const frame = payload?.frame\n    if (frame === undefined) return\n    safely(() => {\n      const sessionId = payload.agent?.session?.id ?? 'unknown'\n      const state = stateFor(sessionId)\n      if (frame.type === 'start') {\n        void state\n        collect(sessionId, {\n          kind: 'attempt-start',\n          at: Date.now(),\n          turn: frame.turn ?? 0,\n          step: frame.step ?? 0,\n          ...(frame.attemptId === undefined ? {} : { attemptId: frame.attemptId }),\n          ...(frame.revision === undefined ? {} : { revision: frame.revision }),\n        })\n        return\n      }\n      if (frame.type === 'chunk') {\n        if (frame.chunk === undefined) return\n        collect(sessionId, { kind: 'chunk', at: frame.time ?? Date.now(), chunk: chunkObservation(frame.chunk) })\n        return\n      }\n      if (frame.type === 'end') {\n        const committed = frame.outcome?.kind === 'committed'\n        collect(sessionId, {\n          kind: 'attempt-end',\n          at: Date.now(),\n          outcome: committed ? 'committed' : 'abandoned',\n          ...(committed && frame.outcome?.eventType !== undefined\n            ? { eventType: frame.outcome.eventType as 'assistant/message' | 'assistant/attempt' }\n            : {}),\n          ...(frame.outcome?.seq === undefined ? {} : { seq: frame.outcome.seq }),\n        })\n      }\n    })\n  }) as (...args: never[]) => unknown, { global: true })\n\n  // --- Durable session records -------------------------------------------\n  ctx.on('session/event', ((...args: unknown[]) => {\n    const session = args[0] as { id?: string } | undefined\n    const event = args[1] as { type?: string; seq?: number; time?: number; data?: unknown } | undefined\n    if (session?.id === undefined || event?.type === undefined) return\n    safely(() => {\n      const sessionId = session.id!\n      switch (event.type) {\n        case 'request/header':\n          collect(sessionId, headerObservation({ seq: event.seq, data: event.data as never }, store) ?? { kind: 'flush', at: Date.now() })\n          break\n        case 'request/context':\n          safely(() => {\n            const observation = contextObservation({ data: event.data as never })\n            if (observation !== undefined) collect(sessionId, observation)\n          })\n          break\n        case 'assistant/message':\n        case 'assistant/attempt':\n          safely(() => {\n            const observation = settlementObservation({ seq: event.seq, time: event.time, data: event.data as never }, store)\n            if (observation !== undefined) collect(sessionId, observation)\n          })\n          break\n        case 'turn/end': {\n          const turn = (event.data as { turn?: number } | undefined)?.turn\n          if (typeof turn === 'number') collect(sessionId, { kind: 'turn-end', turn })\n          break\n        }\n        case 'compaction/start':\n          safely(() => {\n            const observation = compactionObservation({ data: event.data as never })\n            if (observation !== undefined) collect(sessionId, observation)\n          })\n          break\n        case 'llm/retry':\n          safely(() => {\n            const observation = retryObservation({ data: event.data as never })\n            if (observation !== undefined) collect(sessionId, observation)\n          })\n          break\n        case 'tool/call':\n          safely(() => {\n            const observation = toolCallObservation({ seq: event.seq, time: event.time, data: event.data as never }, store)\n            if (observation !== undefined) collect(sessionId, observation)\n          })\n          break\n        case 'tool/result':\n          safely(() => {\n            const observation = toolResultObservation({ time: event.time, data: event.data as never }, store)\n            if (observation !== undefined) collect(sessionId, observation)\n          })\n          break\n        default:\n          break\n      }\n    })\n  }) as (...args: never[]) => unknown, { global: true })\n\n  // --- HTTP surface -------------------------------------------------------\n  const collector: Collector = {\n    store,\n    feed: (sessionId) => sessions.get(sessionId)?.ledger.feed(),\n    sessions: () => [...sessions.keys()],\n    blob: (ref) => store.get(ref),\n    subscribe: (sessionId, sink) => {\n      const state = stateFor(sessionId)\n      state.listeners.add(sink)\n      return () => {\n        state.listeners.delete(sink)\n      }\n    },\n    dispose: () => {\n      disposed = true\n      sessions.clear()\n      if (trailing !== undefined) {\n        clearTimeout(trailing)\n        trailing = undefined\n      }\n    },\n  }\n\n  if (options.serve !== false) {\n    const router = createCacheBricksRouter({\n      feed: (sessionId) => collector.feed(sessionId),\n      sessions: () => collector.sessions(),\n      blob: (ref) => collector.blob(ref),\n      subscribe: (sessionId, sink) => collector.subscribe(sessionId, sink),\n    }, {\n      ...(options.basePath === undefined ? {} : { basePath: options.basePath }),\n      // Prefer the harness's own request policy: it applies the same host, origin\n      // and browser-authentication checks as /api, which matters because /blob\n      // serves whole requests, tool arguments and streams.\n      guard: (request) => {\n        const connection = ctx.get('connection') as\n          | { requestRejection?: (request: unknown) => number | undefined }\n          | undefined\n        return connection?.requestRejection?.(request)\n      },\n    })\n    ctx.inject(['webServer'], (webCtx) => {\n      const server = webCtx.get('webServer') as { register(route: { kind: string; path: string; handler: unknown }): () => void } | undefined\n      if (server === undefined || disposed) return\n      webCtx.effect(() => server.register({ kind: 'prefix', path: options.basePath ?? router.path, handler: router.handler }))\n    })\n  }\n\n  return collector\n}\n"
    },
    {
      "path": "src/host/routes.ts",
      "content": "/**\n * The HTTP surface the browser half talks to.\n *\n * Deliberately not under `/api`: an exact route below `/api` shadows the\n * framework's authenticated prefix route, and the installed plugins that do this\n * (`dsh-reveal-files`) then have to be trusted to check auth themselves. Instead\n * this namespace carries its own, narrow guard — loopback peer plus same-origin —\n * and serves read-only JSON. Nothing here can reach the model: it reads a ledger.\n *\n * Written against structural request/response shapes so it can be unit-tested\n * with two small fakes instead of a live server.\n */\nimport type { BrickFeed } from '../shared/brick'\n\n/** The parts of `IncomingMessage` this router reads. */\nexport interface RouteRequestLike {\n  readonly method?: string\n  readonly url?: string\n  readonly headers: Record<string, string | string[] | undefined>\n  readonly socket?: { readonly remoteAddress?: string }\n}\n\n/** The parts of `ServerResponse` this router uses. */\nexport interface RouteResponseLike {\n  statusCode: number\n  setHeader(name: string, value: string): unknown\n  writeHead?(status: number, headers: Record<string, string>): unknown\n  write?(chunk: string): unknown\n  end(body?: string): unknown\n  on?(event: string, listener: () => void): unknown\n}\n\n/** What the router needs from the collector. */\nexport interface RouterOptions {\n  /**\n   * Pathname the route is registered under. The router must slice exactly this,\n   * or a configured base path silently breaks every sub-route.\n   */\n  readonly basePath?: string\n  /**\n   * The harness's own request policy (`ctx.connection.requestRejection`), which\n   * applies host, origin and browser-authentication checks. Returning a status\n   * refuses the request; returning undefined defers to the local fence.\n   */\n  readonly guard?: (request: RouteRequestLike) => number | undefined\n}\n\n/** What the router needs from the collector. */\nexport interface RouterDeps {\n  /** Current feed for a session, or undefined when nothing was observed yet. */\n  readonly feed: (sessionId: string) => BrickFeed | undefined\n  /** Sessions with a ledger. */\n  readonly sessions: () => readonly string[]\n  /** One stored payload by ref, or undefined when it was evicted. */\n  readonly blob: (ref: string) => unknown\n  /** Subscribe to new bricks; returns an unsubscribe. */\n  readonly subscribe: (sessionId: string, sink: (feed: BrickFeed) => void) => () => void\n}\n\nconst LOOPBACK = new Set(['127.0.0.1', '::1', '::ffff:127.0.0.1'])\n\n/**\n * True when the peer is the local machine.\n *\n * An absent `remoteAddress` is **not** treated as local: this route serves whole\n * requests, tool arguments and model streams, so an unidentifiable peer is\n * refused rather than admitted. (With the harness fence in place this is only a\n * backstop — the official policy runs first.)\n */\nfunction isLoopback(request: RouteRequestLike): boolean {\n  const address = request.socket?.remoteAddress\n  return address !== undefined && LOOPBACK.has(address)\n}\n\n/**\n * True when the request either carries no `Origin` (same-origin fetches from the\n * page, and non-browser clients) or carries one matching the `Host` it was sent\n * to. A cross-origin page cannot read the response either way without CORS, but\n * refusing outright keeps the data out of reach of a stray `<img>`/`<script>`.\n */\nfunction isSameOrigin(request: RouteRequestLike): boolean {\n  const origin = request.headers.origin\n  if (typeof origin !== 'string' || origin === '') return true\n  const host = request.headers.host\n  if (typeof host !== 'string' || host === '') return false\n  try {\n    return new URL(origin).host === host\n  } catch {\n    return false\n  }\n}\n\n/** JSON response helper. */\nfunction json(response: RouteResponseLike, status: number, body: unknown): void {\n  const text = JSON.stringify(body)\n  response.statusCode = status\n  response.setHeader('content-type', 'application/json; charset=utf-8')\n  response.setHeader('cache-control', 'no-store')\n  response.end(text)\n}\n\n/**\n * Build the route handler for the plugin's namespace.\n * @param deps - ledger access.\n * @returns a handler suitable for `webServer.register`, plus the path it serves.\n */\nexport function createCacheBricksRouter(deps: RouterDeps, options: RouterOptions = {}): {\n  readonly path: string\n  readonly handler: (request: RouteRequestLike, response: RouteResponseLike) => void\n} {\n  const path = options.basePath ?? '/cache-bricks'\n  const handler = (request: RouteRequestLike, response: RouteResponseLike): void => {\n    // The harness's policy first: it is the same one /api uses, so this route is\n    // exactly as reachable as the rest of the GUI and no more.\n    const rejection = options.guard?.(request)\n    if (rejection !== undefined) {\n      json(response, rejection, { error: rejection === 401 ? 'unauthenticated' : 'forbidden' })\n      return\n    }\n    if (!isLoopback(request) || !isSameOrigin(request)) {\n      json(response, 403, { error: 'forbidden' })\n      return\n    }\n    const url = new URL(request.url ?? '/', 'http://localhost')\n    const route = url.pathname.slice(path.length)\n    if (request.method !== 'GET' && request.method !== 'HEAD') {\n      json(response, 405, { error: 'method not allowed' })\n      return\n    }\n\n    if (route === '/sessions') {\n      json(response, 200, { sessions: deps.sessions() })\n      return\n    }\n\n    if (route === '/attempts') {\n      const sessionId = url.searchParams.get('sessionId')\n      if (sessionId === null) {\n        json(response, 400, { error: 'sessionId is required' })\n        return\n      }\n      const feed = deps.feed(sessionId)\n      json(response, feed === undefined ? 404 : 200, feed ?? { error: 'no observations for this session yet' })\n      return\n    }\n\n    if (route === '/blob') {\n      const ref = url.searchParams.get('ref')\n      if (ref === null) {\n        json(response, 400, { error: 'ref is required' })\n        return\n      }\n      const value = deps.blob(ref)\n      if (value === undefined) {\n        json(response, 404, { error: 'unknown or evicted ref' })\n        return\n      }\n      json(response, 200, { ref, value })\n      return\n    }\n\n    if (route === '/stream') {\n      const sessionId = url.searchParams.get('sessionId')\n      if (sessionId === null) {\n        json(response, 400, { error: 'sessionId is required' })\n        return\n      }\n      response.writeHead?.(200, {\n        'content-type': 'text/event-stream; charset=utf-8',\n        'cache-control': 'no-cache, no-transform',\n        connection: 'keep-alive',\n      })\n      const send = (event: string, payload: unknown): void => {\n        response.write?.(`event: ${event}\\ndata: ${JSON.stringify(payload)}\\n\\n`)\n      }\n      const current = deps.feed(sessionId)\n      if (current !== undefined) send('feed', current)\n      const unsubscribe = deps.subscribe(sessionId, (feed) => { send('feed', feed) })\n      const heartbeat = setInterval(() => { response.write?.(': hb\\n\\n') }, 25_000)\n      let closed = false\n      const cleanup = (): void => {\n        if (closed) return\n        closed = true\n        clearInterval(heartbeat)\n        unsubscribe()\n      }\n      response.on?.('close', cleanup)\n      return\n    }\n\n    json(response, 404, { error: 'unknown route' })\n  }\n  return { path, handler }\n}\n"
    },
    {
      "path": "src/core/blob-store.ts",
      "content": "/**\n * Content-addressed store for the big half of a brick record.\n *\n * The interesting raw material of a model call — the exact request the provider\n * received, the tool schemas, the request header, the timed stream — is large and\n * mostly identical from attempt to attempt: the 274th call of a session is the\n * 273rd plus a few thousand tokens. Storing it per brick would turn a cache\n * monitor into a duplication engine, so raw payloads are hashed and kept once.\n * Bricks then hold refs, and two bricks that share a prefix share the bytes.\n *\n * Dependency-free (a local SHA-256, no Node builtins), so the same code runs in\n * either half and the store stays a plain data structure with its own unit tests\n * (dedupe, eviction, oversize handling).\n */\nimport { contentRef, utf8Length } from '../shared/sha256'\n\n/** What the store hands back for a stored payload. */\nexport interface StoredBlob {\n  /** Stable content hash, usable as a ref. */\n  readonly hash: string\n  readonly bytes: number\n  /** False when the payload already existed (the common case). */\n  readonly added: boolean\n}\n\n/** Store counters, surfaced to the UI so memory use is never a mystery. */\nexport interface BlobStoreStats {\n  readonly blobs: number\n  readonly bytes: number\n  readonly hits: number\n  readonly misses: number\n  /** Payloads refused for exceeding the per-blob limit. */\n  readonly skipped: number\n  /** Payloads dropped to stay under the total byte budget. */\n  readonly evicted: number\n}\n\n/** Limits that keep a long session from growing without bound. */\nexport interface BlobStoreOptions {\n  /** Largest single payload kept; bigger ones are refused and reported. */\n  readonly maxBlobBytes?: number\n  /** Total bytes kept across all payloads; the least recently used go first. */\n  readonly maxTotalBytes?: number\n  /** Hard cap on payload count, independent of their size. */\n  readonly maxBlobs?: number\n}\n\nconst DEFAULT_MAX_BLOB_BYTES = 4 * 1024 * 1024\nconst DEFAULT_MAX_TOTAL_BYTES = 48 * 1024 * 1024\nconst DEFAULT_MAX_BLOBS = 4096\n\n/**\n * Envelope key under which every payload is stored.\n *\n * Without it a string payload that happens to be valid JSON (`'{\"path\":\"a.ts\"}'`,\n * i.e. exactly the raw tool arguments) would read back as an object, and a\n * forensic store that does not return what you put in is not a store. Wrapping is\n * unambiguous because the store always wraps.\n */\nconst ENVELOPE = 'v'\n\n/** Canonical JSON: key order fixed, so equal values always hash equally. */\nfunction canonicalize(value: unknown): string {\n  return JSON.stringify(value, (_key, item: unknown) => {\n    if (item === null || typeof item !== 'object' || Array.isArray(item)) return item\n    const source = item as Record<string, unknown>\n    const sorted: Record<string, unknown> = {}\n    for (const key of Object.keys(source).sort()) sorted[key] = source[key]\n    return sorted\n  }) ?? 'null'\n}\n\n/** Content-addressed store with LRU eviction. */\nexport class BlobStore {\n  private readonly blobs = new Map<string, { text: string; bytes: number }>()\n  private readonly maxBlobBytes: number\n  private readonly maxTotalBytes: number\n  private readonly maxBlobs: number\n  private bytes = 0\n  private hits = 0\n  private misses = 0\n  private skipped = 0\n  private evicted = 0\n\n  constructor(options: BlobStoreOptions = {}) {\n    this.maxBlobBytes = options.maxBlobBytes ?? DEFAULT_MAX_BLOB_BYTES\n    this.maxTotalBytes = options.maxTotalBytes ?? DEFAULT_MAX_TOTAL_BYTES\n    this.maxBlobs = options.maxBlobs ?? DEFAULT_MAX_BLOBS\n  }\n\n  /**\n   * Store a payload and return its ref.\n   * @param value - any JSON-serializable payload.\n   * @returns the ref and size, or undefined when the payload is too large to keep.\n   */\n  put(value: unknown): StoredBlob | undefined {\n    const text = canonicalize({ [ENVELOPE]: value })\n    const bytes = utf8Length(text)\n    if (bytes > this.maxBlobBytes) {\n      this.skipped += 1\n      return undefined\n    }\n    const hash = contentRef(text)\n    const existing = this.blobs.get(hash)\n    if (existing !== undefined) {\n      // Re-insert to mark it as recently used.\n      this.blobs.delete(hash)\n      this.blobs.set(hash, existing)\n      return { hash, bytes: existing.bytes, added: false }\n    }\n    this.blobs.set(hash, { text, bytes })\n    this.bytes += bytes\n    this.evict()\n    return { hash, bytes, added: true }\n  }\n\n  /**\n   * Read a payload back.\n   * @param hash - the ref returned by {@link put}.\n   * @returns the payload, or undefined when it was never stored or has been evicted.\n   */\n  get(hash: string): unknown {\n    const entry = this.blobs.get(hash)\n    if (entry === undefined) {\n      this.misses += 1\n      return undefined\n    }\n    this.hits += 1\n    this.blobs.delete(hash)\n    this.blobs.set(hash, entry)\n    const parsed = JSON.parse(entry.text) as Record<string, unknown>\n    return parsed[ENVELOPE]\n  }\n\n  /** True when a ref is still resolvable. */\n  has(hash: string): boolean {\n    return this.blobs.has(hash)\n  }\n\n  /** Current counters. */\n  stats(): BlobStoreStats {\n    return {\n      blobs: this.blobs.size,\n      bytes: this.bytes,\n      hits: this.hits,\n      misses: this.misses,\n      skipped: this.skipped,\n      evicted: this.evicted,\n    }\n  }\n\n  /** Drop everything (used when a session ends). */\n  clear(): void {\n    this.blobs.clear()\n    this.bytes = 0\n  }\n\n  private evict(): void {\n    while (\n      this.blobs.size > this.maxBlobs\n      || (this.bytes > this.maxTotalBytes && this.blobs.size > 1)\n    ) {\n      const oldest = this.blobs.keys().next()\n      if (oldest.done === true) return\n      const entry = this.blobs.get(oldest.value)\n      this.blobs.delete(oldest.value)\n      if (entry !== undefined) this.bytes -= entry.bytes\n      this.evicted += 1\n    }\n  }\n}\n"
    },
    {
      "path": "src/shared/metrics.ts",
      "content": "/**\n * Derived telemetry for one attempt.\n *\n * Nothing here needs a new provider API: every number is computed from fields the\n * runtime already reports. Keeping the arithmetic in one pure module means the\n * board, the detail panel and the diff view all quote the same formula — and the\n * formulas can be tested against hand-computed cases instead of eyeballed in a\n * browser.\n */\nimport type { BrickMetrics, BrickUsage } from './brick'\n\n/**\n * Prompt size in tokens.\n *\n * DSH keeps the three prompt buckets disjoint: `inputTokens` is the uncached\n * input, cache reads and cache writes are counted separately. The prompt the\n * provider billed is therefore their sum, and the ratios below divide by it — no\n * guessing at a provider's own `prompt_tokens` convention.\n *\n * @param usage - provider usage for the attempt.\n * @returns the prompt size, or undefined when the attempt reported no usage.\n */\nexport function promptTokensOf(usage: BrickUsage | undefined): number | undefined {\n  if (usage === undefined) return undefined\n  const total = usage.inputTokens + (usage.cacheReadTokens ?? 0) + (usage.cacheWriteTokens ?? 0)\n  return total > 0 ? total : undefined\n}\n\n/** The three prompt buckets as ratios of the prompt. */\nexport interface PromptRatios {\n  readonly promptTokens: number\n  readonly cacheHitRatio: number\n  readonly uncachedRatio: number\n  readonly cacheWriteRatio: number\n}\n\n/**\n * Split the prompt into its three disjoint parts.\n *\n * Returns nothing when the provider reported **no** cache buckets at all: a\n * missing field means \"not reported\", not \"zero cached\", and printing `0.00%`\n * for a provider that never mentions caching is the same lie as printing `n/a`\n * for one that does.\n *\n * @param usage - provider usage for the attempt.\n * @returns the ratios, or undefined when there is no usable prompt size or no\n *   cache accounting to split.\n */\nexport function promptRatiosOf(usage: BrickUsage | undefined): PromptRatios | undefined {\n  if (usage !== undefined && usage.cacheReadTokens === undefined && usage.cacheWriteTokens === undefined) {\n    return undefined\n  }\n  const promptTokens = promptTokensOf(usage)\n  if (promptTokens === undefined || usage === undefined) return undefined\n  const cacheRead = usage.cacheReadTokens ?? 0\n  const cacheWrite = usage.cacheWriteTokens ?? 0\n  return {\n    promptTokens,\n    cacheHitRatio: cacheRead / promptTokens,\n    uncachedRatio: usage.inputTokens / promptTokens,\n    cacheWriteRatio: cacheWrite / promptTokens,\n  }\n}\n\n/**\n * Share of the output that was reasoning tokens.\n * @param usage - provider usage for the attempt.\n * @returns the ratio in `0..1`, or undefined when the provider reports no split.\n */\nexport function reasoningRatioOf(usage: BrickUsage | undefined): number | undefined {\n  if (usage === undefined || usage.reasoningTokens === undefined) return undefined\n  const output = usage.totalTokens !== undefined\n    ? usage.totalTokens - (promptTokensOf(usage) ?? 0)\n    : usage.outputTokens\n  return output > 0 ? usage.reasoningTokens / output : undefined\n}\n\n/**\n * How full the context window was for this request.\n * @param promptTokens - prompt size in tokens.\n * @param contextWindow - the window the request ran against.\n * @returns the ratio in `0..1`, or undefined when either side is unknown.\n */\nexport function contextOccupancyOf(promptTokens: number | undefined, contextWindow: number | undefined): number | undefined {\n  if (promptTokens === undefined || contextWindow === undefined || contextWindow <= 0) return undefined\n  return promptTokens / contextWindow\n}\n\n/** Timestamps collected while an attempt ran. */\nexport interface AttemptTiming {\n  /** When the request was dispatched — from the `llm/stream` hook, not from step start. */\n  readonly dispatchedAt?: number\n  /** When the first stream chunk arrived. */\n  readonly firstTokenAt?: number\n  /** When the usage chunk arrived. */\n  readonly usageAt?: number\n  /** When the terminal frame arrived. */\n  readonly finishAt?: number\n}\n\n/** Timing figures for one attempt, in milliseconds. Absent figures are explicit `undefined`. */\nexport interface AttemptTimingDerived {\n  /**\n   * Dispatch to first token.\n   *\n   * Deliberately *not* measured from `step/start`: that frame is emitted before\n   * routing, adapter setup and retry policy, so it would flatter the number.\n   */\n  readonly ttftMs: number | undefined\n  /** Dispatch to the terminal frame. */\n  readonly durationMs: number | undefined\n  /** Generation time (first token to finish), used as the TPS denominator. */\n  readonly generationMs: number | undefined\n  /** Output tokens per second over the generation window. */\n  readonly tps: number | undefined\n}\n\n/**\n * Derive timing and throughput.\n * @param timing - the timestamps the collector captured.\n * @param outputTokens - output tokens for the attempt, when known.\n * @returns the derived timings, each present only when its inputs are.\n */\nexport function deriveTiming(timing: AttemptTiming, outputTokens?: number): AttemptTimingDerived {\n  const { dispatchedAt, firstTokenAt, finishAt } = timing\n  const ttftMs = dispatchedAt !== undefined && firstTokenAt !== undefined\n    ? Math.max(0, firstTokenAt - dispatchedAt)\n    : undefined\n  const durationMs = dispatchedAt !== undefined && finishAt !== undefined\n    ? Math.max(0, finishAt - dispatchedAt)\n    : undefined\n  const generationMs = firstTokenAt !== undefined && finishAt !== undefined\n    ? Math.max(0, finishAt - firstTokenAt)\n    : undefined\n  const tps = generationMs !== undefined && generationMs > 0 && outputTokens !== undefined && outputTokens > 0\n    ? outputTokens / (generationMs / 1000)\n    : undefined\n  return { ttftMs, durationMs, generationMs, tps }\n}\n\n/** Character and chunk counters accumulated from the stream. */\nexport interface StreamCounters {\n  readonly chunkCount: number\n  readonly textChars: number\n  readonly reasoningChars: number\n  readonly toolCallCount: number\n}\n\n/** An empty counter set, so a record is never missing its shape. */\nexport const EMPTY_COUNTERS: StreamCounters = { chunkCount: 0, textChars: 0, reasoningChars: 0, toolCallCount: 0 }\n\n/**\n * Assemble the metrics block.\n * @param usage - provider usage, when the attempt produced any.\n * @param timing - captured timestamps.\n * @param counters - stream counters.\n * @param contextWindow - the window the request ran against.\n * @returns a fully populated metrics block (absent figures stay absent).\n */\nexport function deriveMetrics(\n  usage: BrickUsage | undefined,\n  timing: AttemptTiming,\n  counters: StreamCounters,\n  contextWindow?: number,\n): BrickMetrics {\n  // The prompt size is knowable whenever the provider reports any prompt bucket,\n  // even if it never mentions caching; the *split* is what needs both.\n  const promptTokens = promptTokensOf(usage)\n  const ratios = promptRatiosOf(usage)\n  const derived = deriveTiming(timing, usage?.outputTokens)\n  const occupancy = contextOccupancyOf(promptTokens, contextWindow)\n  const reasoningRatio = reasoningRatioOf(usage)\n  return {\n    ...(promptTokens === undefined ? {} : { promptTokens }),\n    ...(ratios === undefined ? {} : {\n      cacheHitRatio: ratios.cacheHitRatio,\n      uncachedRatio: ratios.uncachedRatio,\n      cacheWriteRatio: ratios.cacheWriteRatio,\n    }),\n    ...(reasoningRatio === undefined ? {} : { reasoningRatio }),\n    ...(occupancy === undefined ? {} : { contextOccupancy: occupancy }),\n    ...(derived.ttftMs === undefined ? {} : { ttftMs: derived.ttftMs }),\n    ...(derived.durationMs === undefined ? {} : { durationMs: derived.durationMs }),\n    ...(derived.tps === undefined ? {} : { tps: derived.tps }),\n    ...(timing.dispatchedAt === undefined ? {} : { dispatchedAt: timing.dispatchedAt }),\n    ...(timing.firstTokenAt === undefined ? {} : { firstTokenAt: timing.firstTokenAt }),\n    ...(timing.usageAt === undefined ? {} : { usageAt: timing.usageAt }),\n    ...(timing.finishAt === undefined ? {} : { finishAt: timing.finishAt }),\n    chunkCount: counters.chunkCount,\n    textChars: counters.textChars,\n    reasoningChars: counters.reasoningChars,\n    toolCallCount: counters.toolCallCount,\n  }\n}\n\n/** One side of a brick-to-brick comparison. */\nexport interface FieldDelta {\n  readonly label: string\n  readonly before: string\n  readonly after: string\n  /** True when the two sides differ, i.e. this is what to look at. */\n  readonly changed: boolean\n  /** Set for hashes: equal hashes mean an identical payload, not merely equal text. */\n  readonly sameHash?: boolean\n}\n\n/** Format a number with thousands separators, or an em dash when absent. */\nexport function showNumber(value: number | undefined): string {\n  return value === undefined ? '—' : value.toLocaleString('en-US')\n}\n\n/** Format a ratio as a percentage, or an em dash when absent. */\nexport function showPercent(value: number | undefined, digits = 2): string {\n  return value === undefined ? '—' : `${(value * 100).toFixed(digits)}%`\n}\n\n/** Format a duration in ms as seconds, or an em dash when absent. */\nexport function showSeconds(value: number | undefined): string {\n  return value === undefined ? '—' : `${(value / 1000).toFixed(2)}s`\n}\n\n/** Format a hash for display, keeping it short but identifiable. */\nexport function showHash(value: string | undefined): string {\n  return value === undefined ? '—' : value.slice(0, 12)\n}\n"
    },
    {
      "path": "src/client/index.tsx",
      "content": "import { useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react'\nimport type {} from '@deepseek-ai/dsh-client-ui-slots'\n// The renderer owns the `ctx.slots` registry this half registers into; the other\n// two supply the node contract and the chat-store/selector face it reads.\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-conversation/client'\nimport type { ReactElement } from 'react'\nimport type { ChatSnapshot } from '@deepseek-ai/dsh-client-ui-chat/client'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { cacheBricksDefinition, type CacheBricksNodeData, type StepSample } from './cache-bricks-node'\nimport { badgeLogLine, badgeStatus, brickLabel, hasCacheFields, ttftMs } from './logic'\nimport { CacheTetrisBoard } from './tetris-view'\nimport type { Brick } from './tetris'\nimport { locateResultOf, type RevealOutcome } from './reveal'\nimport { BrickFeedClient } from './feed'\nimport { BrickPanel, type JumpReport, type RawKind, type TranscriptState } from './panel'\nimport { BoardWorld, type BoardData, type StepReading } from './bricks'\nimport {\n  durableEventsOf, durableEventsOutside, ensureTurnTranscriptLoaded, HistoryPager, loadRequestForTurn, logRawPayload,\n  onWindowChange, readTranscript, resolveHistoricalStep, sessionFaceOf, windowKeyOfSnapshot,\n  type LogRawKind,\n  type LoadReport, type LoadRequest, type SessionFace,\n} from './navigation'\nimport { HistoryScene, type SceneDemand } from './history-scene'\nimport { replayBlobPuts, replayBlobPutsSkipped } from '../core/replay'\nimport { diffBricks } from '../shared/diff'\nimport type { BrickFeed, BrickRecord } from '../shared/brick'\n\n\n/**\n * Selector hook over the Chat store, declared structurally: ui-chat's own\n * `UseChat` alias resolves through `@deepseek-ai/dsh-client-store`, a runtime\n * package this plugin deliberately does not depend on (it never imports it at\n * runtime), so the shape is restated here instead.\n */\n/** The raw kinds a replayed brick's payloads can be read out of the log for. */\nconst LOG_RAW_KINDS: readonly string[] = ['stream', 'replay', 'header']\n\ntype ChatSelector = <T>(selector: (snapshot: ChatSnapshot) => T) => T\n\n/** The session seat delivers the Chat store selector (ui-chat's SessionStandardProps). */\ninterface CacheBricksBoardProps {\n  useChat?: ChatSelector\n  /** Session this seat belongs to (session-scoped seat), when the carrier provides it. */\n  sessionId?: string\n}\n\n/** One console line per step and badge content, surviving React remounts. */\nconst logged = new Set<string>()\n\n/**\n * The feed client, kept outside the component so the panel's raw loader can reach\n * it without threading a callback through every level.\n */\nconst feedClientRef: { current: BrickFeedClient | undefined } = { current: undefined }\n\n/**\n * The client context, kept only so the official services can be resolved **at use time**.\n *\n * They cannot be resolved once at startup: the sessions service is provided *after* this\n * plugin's client half applies (measured on 0.1.7-rc.1: `ctx.get('sessions')` is undefined\n * inside `apply` and present two seconds later), so anything captured early would be a\n * permanent `undefined` — a jump feature that never loads and never says why.\n */\nconst ctxRef: { current: Context | undefined } = { current: undefined }\n\n/** How one load ended, in one short sentence for the panel. */\nexport function loadText(report: LoadReport): string {\n  switch (report.status) {\n    case 'not-needed':\n      return 'the row was already on screen'\n    case 'already-loaded':\n      return `history already covered seq ${String(report.seq)}`\n    case 'loaded':\n      return `loaded history through seq ${String(report.seq)}`\n        + (report.rendered === false ? ' (the transcript has not rendered it)' : '')\n    case 'nothing-to-load':\n      return 'this brick has no row in the transcript to load for'\n    case 'no-seq':\n      return 'the record carries no log position for this attempt, so there is nothing to load'\n    case 'no-loader':\n      return 'this core did not give the plugin a session face, so nothing could be loaded'\n    case 'timeout':\n      return `history was requested but the window still does not cover seq ${String(report.seq)}`\n      + (report.rendered === false ? ' — and the transcript shows no new rows either' : '')\n  }\n}\n\n/**\n * The one loader this session's bricks use, resolved fresh on every call.\n *\n * @param sessionId - the session the board is showing.\n * @returns a function that makes the window cover a target's log position.\n */\nfunction loaderFor(sessionId: string | undefined): (request: LoadRequest) => Promise<LoadReport> {\n  return async (request) => ensureTurnTranscriptLoaded(faceFor(sessionId), request)\n}\n\n/**\n * The session's own log, read a **scene** at a time — the board's historical source.\n *\n * The collector only ever sees this process, so a brick older than it used to lose its type, its\n * lifecycle and its target. The log has held all of that all along; `./history-scene` reads it\n * with the same observations the collector uses, so a replayed brick means what a live one means,\n * minus the request capture the log never had.\n *\n * What changed in 0.1.4 is *how much* of it is read at once. Replaying the whole window worked\n * while the window was one session's tail; once it could page older history in, the replay grew\n * past the ledger's brick budget and the oldest bricks came back typed by the client fold. The\n * board now says which Turns and steps are on screen, and only that slice is replayed.\n *\n * One service per session, kept outside the component so a re-render cannot lose a warm scene.\n */\nlet historySceneRef: { sessionId: string; scene: HistoryScene } | undefined\n\nfunction historySceneOf(sessionId: string | undefined): HistoryScene | undefined {\n  if (sessionId === undefined || sessionId === '') return undefined\n  // A different session is a different window: replace the service rather than accumulating one\n  // raw-payload store per session visited.\n  if (historySceneRef?.sessionId !== sessionId) historySceneRef = { sessionId, scene: new HistoryScene({ sessionId }) }\n  return historySceneRef.scene\n}\n\n/** The session face for this board's session, resolved fresh on every call. */\nfunction faceFor(sessionId: string | undefined): SessionFace | undefined {\n  try { return sessionFaceOf(ctxRef.current?.get('sessions'), sessionId) } catch { return undefined }\n}\n\n/**\n * How often the render path asked about the session window, and how often the answer was \"it\n * moved, copy it\".\n *\n * `asked` counts renders of this component; `materialized` counts the ones that had to walk and\n * sort the durable window. The gap between them is the whole point of asking the snapshot for its\n * revision first: a panel opening, a tab switching, a notice timing out — none of those move the\n * window, and none of them may pay for it. Read-only, for the verification scripts.\n */\nconst windowNotes = { asked: 0, materialized: 0, deltas: 0 }\n\n/**\n * Hand the scene the window the session holds now, at the price of one comparison.\n *\n * `durableEvents` copies and sorts the entire window, and this runs on **every** render — a\n * selection, a tab switch, a transcript read, the scene the board just asked for. So the window is\n * asked about itself first: its own revision counter, plus its ends and its length\n * ({@link windowKeyOfSnapshot}), says whether anything moved, and only a window that moved is worth\n * materializing. The scene still decides by its exact key, so a cheap key that over-reports costs\n * one index rebuild — never a stale one.\n *\n * @param scene - the scene service for this session.\n * @param face - the session face, when the core publishes one.\n * @returns true when this call rebuilt the scene's index.\n */\nfunction noteWindow(scene: HistoryScene, face: SessionFace | undefined): boolean {\n  const snapshot = face?.eventSource?.getSnapshot()\n  if (snapshot === undefined) return false\n  windowNotes.asked += 1\n  const key = windowKeyOfSnapshot(snapshot)\n  if (scene.indexKey === key) return false\n  windowNotes.materialized += 1\n  // A log is append-only, so most window changes are *growth*: a page landed at the older end, or a\n  // Turn settled at the newer one. Then there is nothing to re-read — ask the snapshot for what it\n  // holds outside the range the index already covers, and prove it is the whole difference by\n  // counting (`indexed + older + newer === total`). Anything else is a different window.\n  const bounds = scene.windowBounds\n  if (bounds !== undefined) {\n    const { older, newer, total } = durableEventsOutside(snapshot, bounds)\n    if (scene.indexedCount + older.length + newer.length === total) {\n      windowNotes.deltas += 1\n      return scene.windowGrew(older, newer, key)\n    }\n  }\n  return scene.window(durableEventsOf(snapshot), key)\n}\n\n/**\n * Everything the session knows about one brick's place in the conversation.\n *\n * A collected brick answers through its target (which says which row it is, and which\n * log position that row needs). A folded brick has no target — but it still has a\n * turn, a step and the seq it was measured from, which is enough to read the turn.\n */\nfunction transcriptQueryOf(record: BrickRecord): { turn: number; step: number; request: LoadRequest } | undefined {\n  if (record.identity.turn <= 0) return undefined\n  return {\n    turn: record.identity.turn,\n    step: record.identity.step,\n    request: { ...loadRequestForTurn(record.settlementSeq), turn: record.identity.turn },\n  }\n}\n\n/**\n * Providers that have ever reported a cache-accounting field in this page. Once\n * a provider is in this set, a later request without cache fields is read as a\n * genuine `0` read (a full miss) instead of being left unconfirmed.\n */\nconst providersWithCacheEvidence = new Set<string>()\n\n/** One detailed console warning per provider that never reports cache fields. */\nconst unconfirmedNotified = new Set<string>()\n\n/** Every materialized Turn reading, oldest first (visible or hidden nodes). */\nfunction selectReadings(snapshot: ChatSnapshot): readonly CacheBricksNodeData[] {\n  const turns: CacheBricksNodeData[] = []\n  for (const node of snapshot.nodes.values()) {\n    if (node.kind !== 'cache-bricks') continue\n    const data = node.data as CacheBricksNodeData | undefined\n    if (data !== undefined) turns.push(data)\n  }\n  return turns.sort((left, right) => left.turn - right.turn)\n}\n\n/** Whether this page has evidence that the step's provider reports cache fields. */\nfunction evidenceFor(sample: StepSample): boolean {\n  return hasCacheFields(sample.usage)\n    || (sample.provider !== undefined && providersWithCacheEvidence.has(sample.provider))\n}\n\n/**\n * The brick board: each real model request attempt drops a brick into its Turn's column,\n * the newest Turn anchored at the board's right edge, so a finished Turn pushes the older\n * columns one cell to the left and the next Turn stacks in the free column. It renders\n * nothing into the session seat it is mounted in — the board is a body-level overlay (see\n * {@link CacheTetrisBoard}) parked in the blank gutter beside the transcript, because no\n * seat exists there.\n *\n * A brick is an attempt, not a step: this harness retries, and the retry is a second\n * request with its own cache outcome. What each brick *shows* is folded from the session\n * event feed per step, so the fold is a fallback with a different granularity — see\n * `./bricks` — and those reduced bricks make no claim about a transcript row.\n */\nfunction CacheBricksBoard(props: CacheBricksBoardProps): ReactElement | null {\n  // `useChat` arrives from ui-chat's SessionStandardProps merge. The guard is\n  // invariant for a given seat (a carrier either delivers the face or never\n  // does), so the hook order stays stable across renders.\n  const turns = typeof props.useChat === 'function' ? props.useChat(selectReadings) : undefined\n  const sessionId = typeof props.sessionId === 'string' ? props.sessionId : undefined\n  const boardRef = useRef<CacheTetrisBoard | undefined>(undefined)\n  const selectedRef = useRef<string | undefined>(undefined)\n  const [selected, setSelected] = useState<string | undefined>(undefined)\n  const [tab, setTab] = useState('transcript')\n  const [comparing, setComparing] = useState(false)\n  const [raw, setRaw] = useState<Partial<Record<RawKind, unknown>>>({})\n  const [jump, setJump] = useState<JumpReport | undefined>(undefined)\n  const [transcript, setTranscript] = useState<TranscriptState>({ status: 'idle' })\n  const [previewReload, setPreviewReload] = useState(0)\n  const [notice, setNotice] = useState<{ state: 'loading' | 'success' | 'error'; text: string } | undefined>(undefined)\n  const feed = useFeed(sessionId)\n  useEffect(() => {\n    if (notice?.state !== 'success') return\n    const timer = setTimeout(() => setNotice(undefined), 3500)\n    return () => clearTimeout(timer)\n  }, [notice])\n\n  // Evidence is recorded during render, not from an effect: it is an idempotent\n  // module-level memo, and classifying a step must not depend on whether an\n  // earlier step's commit already ran its effects. Only the console once-gates\n  // below need commit semantics.\n  if (turns !== undefined) {\n    for (const data of turns) {\n      for (const sample of data.steps) {\n        if (hasCacheFields(sample.usage) && sample.provider !== undefined) {\n          providersWithCacheEvidence.add(sample.provider)\n        }\n      }\n    }\n  }\n  const signature = turns === undefined ? '' : turns.map((data) => [\n    data.turn,\n    data.ended ? 'e' : 'o',\n    data.steps.map((sample) => `${String(sample.step)}:${String(sample.usage?.inputTokens ?? '')}:${String(sample.usage?.cacheReadTokens ?? '')}`).join(','),\n  ].join('|')).join(';')\n\n  // Console side effects run after commit: warn once per provider that reports\n  // no cache fields, and log one line per step. A discarded React render must\n  // not consume the once-gates or drop the log line.\n  useEffect(() => {\n    if (turns === undefined) return\n    for (const data of turns) {\n      for (const sample of data.steps) {\n        if (sample.usage === undefined) continue\n        if (\n          sample.provider !== undefined\n          && !hasCacheFields(sample.usage)\n          && !providersWithCacheEvidence.has(sample.provider)\n          && !unconfirmedNotified.has(sample.provider)\n        ) {\n          unconfirmedNotified.add(sample.provider)\n          console.warn(\n            `[dsh-cache-bricks] provider \"${sample.provider}\" returned usage without `\n            + 'cacheReadTokens/cacheWriteTokens; no cache field has been seen for it, so its steps '\n            + 'show \"n/a\" instead of a percentage.',\n          )\n        }\n        const decided = badgeStatus({ usage: sample.usage, hasCacheEvidence: evidenceFor(sample) })\n        if (decided === null) continue\n        const lineKey = `${String(data.turn)}:${String(sample.step)}:${decided.label}`\n        if (logged.has(lineKey)) continue\n        logged.add(lineKey)\n        console.info(badgeLogLine(decided, {\n          turn: data.turn,\n          step: sample.step,\n          provider: sample.provider,\n          at: sample.usageTime ?? Date.now(),\n        }))\n      }\n    }\n  }, [signature])\n\n  // The reporting is shared by the board's double click and the panel's button, so the two\n  // can never drift apart about what a jump reached. It lives in a ref because the board is\n  // created once, imperatively, and must not be re-created when a render brings a new closure.\n  const reporter = useRef<(brick: Brick, outcome: RevealOutcome) => void>(() => {})\n  reporter.current = (brick, outcome) => {\n    const where = brick.turn > 0 ? `turn ${String(brick.turn)} step ${String(brick.step)}` : 'an auxiliary call'\n    const row = outcome.element?.getAttribute?.('data-chat-node-key')\n    const detail = [\n      loadText(outcome.load),\n      outcome.expanded ? 'opened a collapsed group' : undefined,\n      row === undefined ? undefined : row,\n    ].filter((part): part is string => part !== undefined).join(', ')\n    const located = locateResultOf(outcome)\n    setNotice({\n      state: located.status === 'exact' ? 'success' : 'error',\n      text: located.status === 'exact-not-visible'\n        // Found, and the reader cannot see it: a capped process group is clipping the row. Say that\n        // rather than \"located\" — the whole point of the check is that this case stops lying.\n        ? '找到了这一行，但它被这一轮的过程组裁掉了，屏幕上看不见；没有高亮，也不当作定位成功。'\n        : outcome.accuracy === 'exact'\n        // A folded brick lands on its **step**: say so, so a step-level landing is never read\n        // as \"this is the request you clicked\" (the board's dashes say it too, but the notice\n        // is what a reader actually reads).\n        ? brick.estimated === true\n          ? `已定位：第 ${String(brick.turn)} 轮 · 第 ${String(brick.step)} 步（历史折叠砖：step 级，不含 attempt）`\n          : `已定位：第 ${String(brick.turn)} 轮 · 第 ${String(brick.step)} 步`\n        : outcome.fellBack === true\n          // Reached, but the row is the same step's other half: say which half is missing\n          // rather than reporting a miss that did not happen (or a success that is not one).\n          ? '本步骤这一半没有渲染行；已定位到同一步骤的另一半（未高亮）。'\n          : outcome.load.status === 'nothing-to-load'\n            ? '这块砖没有原对话行；单击可查看详情。'\n            : '未找到这块砖的原对话行，没有跳到邻近内容。单击可查看对话预览和诊断。',\n    })\n    setJump({\n      turn: brick.turn,\n      step: brick.step,\n      accuracy: outcome.accuracy,\n      row: outcome.row,\n      load: outcome.load,\n      locate: located,\n    })\n    console.info(\n      `[dsh-cache-bricks] ${where}: ${outcome.accuracy} landing · locate=${located.status}`\n      + `${detail === '' ? '' : ` (${detail})`}`,\n    )\n  }\n\n  /**\n   * The pager, and the one thing to do when a page lands: rebuild the index from the window the\n   * session now holds, re-cut the screen the reader is on, and let React see the new scene.\n   *\n   * The board asks for a page on every paint near the left edge, so both halves are idempotent:\n   * `need()` answers `stalled`/`busy`/`no-more` without a request, and `window()` rescans only\n   * when the window actually moved.\n   */\n  const pagerRef = useRef<HistoryPager | undefined>(undefined)\n  const refreshScene = useRef<() => void>(() => {})\n  refreshScene.current = () => {\n    const scene = historySceneOf(sessionId)\n    if (scene === undefined) return\n    noteWindow(scene, faceFor(sessionId))\n    scene.refresh()\n  }\n  pagerRef.current ??= new HistoryPager(undefined)\n  pagerRef.current.aim(faceFor(sessionId))\n\n  /**\n   * The scene service is a store, and the scene it currently holds is its snapshot: when a\n   * scene is cut, the key changes and React re-renders. A lookup that hit the memo changes\n   * nothing, so panning inside a scene costs no renders at all.\n   */\n  const scene = historySceneOf(sessionId)\n  useSyncExternalStore(\n    (listener) => scene?.subscribe(listener) ?? (() => {}),\n    () => scene?.scene?.key ?? '',\n    // A server render has no window and no scene: the board is a browser overlay, and the seat\n    // it is mounted into must render nothing at all (see `client-bundle.spec.ts`).\n    () => '',\n  )\n\n  // A page can also arrive from outside this board (a jump, the conversation's own loader).\n  // Only a window that grew at the *older* end changes the index, and that is one number to\n  // compare — an append is picked up by the ordinary render path.\n  const oldestSeq = useRef<number | undefined>(undefined)\n  useEffect(() => {\n    if (scene === undefined) return undefined\n    return onWindowChange(faceFor(sessionId), () => {\n      const face = faceFor(sessionId)\n      const oldest = face?.eventSource?.getSnapshot()?.entries?.[0]?.event?.seq\n      if (oldest === oldestSeq.current) return\n      oldestSeq.current = oldest\n      refreshScene.current()\n    })\n  }, [sessionId, scene])\n\n  // The board is created once and driven imperatively: it lives outside React's\n  // tree (body-level overlay) and must never be re-created by a render.\n  useEffect(() => {\n    const board = new CacheTetrisBoard({\n      // Single click reads in a preview. Double click closes it and locates the exact row.\n      onSelect: (key) => {\n        selectedRef.current = key\n        setSelected(key)\n        boardRef.current?.setSelected(key)\n        setTab('transcript')\n        setNotice(undefined)\n        setPreviewReload((version) => version + 1)\n        setComparing(false)\n        setRaw({})\n        setJump(undefined)\n        // A new brick means a new conversation to read: the old one is not this brick's.\n        setTranscript({ status: 'idle' })\n      },\n      onRevealStart: (brick) => {\n        selectedRef.current = undefined\n        setSelected(undefined)\n        setTranscript({ status: 'idle' })\n        boardRef.current?.setSelected(brick.key)\n        setNotice({ state: 'loading', text: '正在定位这块砖对应的原对话…' })\n      },\n      load: loaderFor(sessionId),\n      // A folded brick names a step, not a row: ask the durable log which row that step\n      // became, once the jump has loaded the history the answer lives in.\n      resolve: (target) => resolveHistoricalStep(faceFor(sessionId), target),\n      // The board repeats what it actually reached rather than upgrading a near miss to a\n      // success: `exact` is the brick's own row, `context` the Turn header, `none` nothing.\n      onRevealed: (brick, outcome) => { reporter.current(brick, outcome) },\n      // What the reader is looking at, sent only when it changes. The scene service replays\n      // exactly that slice and announces the result, which re-renders this component and hands\n      // the board a board built from exact records — one round trip, no polling.\n      onScene: (demand: SceneDemand) => { historySceneOf(sessionId)?.demand(demand) },\n      // Near the left edge of the history this client holds: ask for a page. The pager decides\n      // whether asking means anything (`hasMore`, a page in flight, the same window twice), and\n      // a page that landed is a new window — rebuild the index and re-cut the reader's screen.\n      onNeedOlder: () => {\n        void pagerRef.current?.need().then((status) => { if (status === 'loaded') refreshScene.current() })\n      },\n    })\n    selectedRef.current = undefined\n    setSelected(undefined)\n    setNotice(undefined)\n    boardRef.current = board\n    board.start()\n    // The one place a browser check can count what a pan cost. A pan asks the data layer for a\n    // scene, the data layer replays a slice of the log, and React re-renders the board from it —\n    // all of it invisible in the DOM, which is why `scripts/test-scroll.mjs` used to be able to\n    // assert the *shape* of a long board and nothing about the price of moving it. The handle\n    // answers with the current numbers and nothing else: read-only, and read by nothing in the\n    // plugin. See `docs/verification.md`.\n    const handle = globalThis as { __dshCacheBricksStats?: () => unknown }\n    handle.__dshCacheBricksStats = () => ({\n      board: boardRef.current?.stats,\n      scene: historySceneRef?.scene.stats,\n      // The step cache is where a re-visited screen is answered from (see `HistoryScene.stepStats`):\n      // `hits` should move on a pan back over ground already covered, and `misses` should not.\n      steps: historySceneRef?.scene.stepStats,\n      window: { ...windowNotes },\n      // The float pan the view is showing against the whole-cell pan the DOM is painted at: the\n      // difference is what the motion plane is carrying, in cells.\n      motion: boardRef.current?.motionState,\n      // What the data layer cost: a pan should move `columnsRebuilt` and nothing else.\n      world: worldRef.current?.world.stats,\n      // Raw payload hashing: a scene replay is lazy, so `hashes` must stay flat while `skipped`\n      // grows — the bytes are still in the log, read on demand (`logRawPayload`).\n      raw: { hashes: replayBlobPuts(), skipped: replayBlobPutsSkipped() },\n    })\n    return () => {\n      boardRef.current = undefined\n      board.dispose()\n    }\n  }, [sessionId])\n\n  // Three sources, merged rather than swapped: the collector knows this process's attempts\n  // and nothing older, a replay of the session's own log knows every attempt the client is\n  // holding, and the per-step fold is what is left for a core with no session face at all.\n  // A feed that answered with anything used to replace the history outright, so resuming an\n  // old session dropped every brick older than the collector — and the bricks it dropped were\n  // the ones that had a type and a row to go to. See `boardFromSources`.\n  //\n  // Both the fold and the merge are memos, and that is a *drag* concern: `useChat` memoizes its\n  // selection, so `turns` keeps its identity across every render the chat store did not cause —\n  // which is every render a pan causes. Without the memos each of those re-read the whole fold and\n  // rebuilt the whole board, handed the board a **new** columns array, and so forced a repaint\n  // whose tallest-column memo had just been invalidated. A drag would then cost O(session) per\n  // frame no matter how little of it the board draws.\n  const readings = useMemo(() => readingsOf(turns), [turns])\n  const live = feed !== undefined && feed.sessionId === sessionId ? feed : undefined\n  // Note the window the session holds now; the scan happens only when it moved, and the scene\n  // for the reader's last screen is re-cut silently so this render never sees a stale one.\n  if (scene !== undefined) noteWindow(scene, faceFor(sessionId))\n  const replayed = scene?.scene?.feed\n  // One world per session, kept outside the memo: a scene change is a *patch* to it, not a rebuild.\n  // The memo below still runs when a source changes — that is the point — but the work it does is\n  // now the scene (plus the columns it touched), where it used to be the whole session.\n  const worldRef = useRef<{ sessionId: string | undefined; world: BoardWorld } | undefined>(undefined)\n  if (worldRef.current === undefined || worldRef.current.sessionId !== sessionId) {\n    worldRef.current = { sessionId, world: new BoardWorld() }\n  }\n  const world = worldRef.current.world\n  const data: BoardData = useMemo(\n    () => world.board({\n      ...(live === undefined ? {} : { live }),\n      ...(replayed === undefined ? {} : { replay: replayed }),\n      readings,\n    }),\n    [world, live, replayed, readings],\n  )\n\n  useEffect(() => {\n    boardRef.current?.setColumns(data.columns, data.titles, data.aux, data.tallest)\n    // The notice is for a board that is *entirely* folded, where \"one brick per step,\n    // no attempt telemetry\" is true of every brick. In a mixed board the claim is per\n    // brick — the restored ones are drawn dashed — so a whole-board notice would lie.\n    boardRef.current?.setEstimated(data.estimated === true)\n  }, [sessionId, data.columns, data.titles, data.aux, data.estimated])\n\n  // A brick that scrolled out of the feed (or a session switch) closes the panel\n  // rather than leaving it describing something no longer on the board.\n  const record = selected === undefined ? undefined : data.records.get(selected)\n  useEffect(() => {\n    if (selected !== undefined && record === undefined) {\n      selectedRef.current = undefined\n      setSelected(undefined)\n      boardRef.current?.setSelected(undefined)\n    }\n  }, [selected, record])\n\n  // Read immediately on selection (no extra tab/button). Async results are owned by the\n  // selected brick and session; closing, switching or double-clicking invalidates the read.\n  useEffect(() => {\n    if (record === undefined || selected === undefined) return\n    let cancelled = false\n    const key = selected\n    const isCurrent = (): boolean => !cancelled && selectedRef.current === key\n    setTranscript({ status: 'loading' })\n    const query = transcriptQueryOf(record)\n    const face = faceFor(sessionId)\n    if (query === undefined || face === undefined) {\n      setTranscript({ status: 'unavailable', report: { status: query === undefined ? 'nothing-to-load' : 'no-loader' } })\n      return () => { cancelled = true }\n    }\n    void ensureTurnTranscriptLoaded(face, query.request, isCurrent).then((report) => {\n      if (!isCurrent()) return\n      const view = readTranscript(face, query.turn, query.step, query.request.seq, {\n        exactAttempt: record.observedBy !== 'client',\n        ...(record.observedBy === 'client' ? {} : { callIds: record.tools.map((call) => call.callId) }),\n      })\n      setTranscript(view === undefined ? { status: 'unavailable', report } : { status: 'ready', view, report })\n    }).catch((error: unknown) => {\n      if (!isCurrent()) return\n      console.warn('[dsh-cache-bricks] preview read failed', error)\n      // `seq` is optional under `exactOptionalPropertyTypes`: report the position only when\n      // there is one, rather than carrying an explicit `undefined` into the panel's copy.\n      setTranscript({\n        status: 'unavailable',\n        report: { status: 'timeout', ...(query.request.seq === undefined ? {} : { seq: query.request.seq }) },\n      })\n    })\n    return () => { cancelled = true }\n    // Feed objects are refreshed regularly; re-read on semantic changes, not every feed poll.\n  }, [sessionId, selected, previewReload, record?.settlementSeq, record?.settlement, record?.tools.length])\n\n  const notification = notice === undefined ? null : (\n    <div role=\"status\" aria-live=\"polite\" data-cache-bricks-notice={notice.state}\n      style={{ position: 'fixed', top: '64px', right: '20px', zIndex: 1001, maxWidth: 'min(420px, 90vw)',\n        padding: '10px 14px', borderRadius: '8px', background: 'var(--dsw-alias-bg-layer-1, #18202b)',\n        color: 'var(--dsw-alias-label-primary, #e5e7eb)', boxShadow: '0 4px 20px #0004', fontSize: '13px' }}>\n      {notice.text}\n      <button type=\"button\" onClick={() => setNotice(undefined)} aria-label=\"关闭定位提示\" style={{ marginLeft: '10px' }}>×</button>\n    </div>\n  )\n  if (record === undefined) return notification\n\n  const allBricks = [...data.columns.flatMap((column) => column.bricks), ...data.aux]\n  const index = data.order.indexOf(record.identity.id)\n  const previous = index > 0 ? data.records.get(data.order[index - 1]!) : undefined\n  return (\n    <>\n    {notification}\n    <BrickPanel\n      record={record}\n      tab={tab}\n      onTab={setTab}\n      onClose={() => {\n        selectedRef.current = undefined\n        setSelected(undefined)\n        boardRef.current?.setSelected(undefined)\n      }}\n      {...(previous === undefined ? {} : {\n        onCompare: () => { setComparing((open) => !open) },\n        ...(comparing ? { diff: diffBricks(previous, record) } : {}),\n      })}\n      {...(jump === undefined ? {} : { jump })}\n      onLocate={() => {\n        const brick = allBricks.find((candidate) => candidate.key === record.identity.id)\n        if (brick === undefined) return\n        void boardRef.current?.goToBrick(brick)\n      }}\n      transcript={transcript}\n      onLoadTranscript={() => setPreviewReload((version) => version + 1)}\n      raw={raw}\n      onLoadRaw={(kind) => {\n        const ref = kind === 'request'\n          ? record.request.requestRef\n          : kind === 'messages'\n            ? record.request.messageHashesRef\n            : kind === 'header'\n              ? record.request.headerRef\n              : kind === 'toolHistory'\n                ? record.request.toolHistoryRef\n                : kind === 'stream'\n                  ? record.raw.streamRef\n                  : record.raw.replayRef\n        if (ref === undefined) {\n          // No ref means nothing was hashed for this brick — a replayed one (see `raw: 'lazy'`).\n          // Its payloads are the session's own events, so read the one that was asked for.\n          const face = faceFor(sessionId)\n          const value = LOG_RAW_KINDS.includes(kind) ? logRawPayload(face, record, kind as LogRawKind) : undefined\n          if (value === undefined || selectedRef.current !== record.identity.id) return\n          setRaw((current) => ({ ...current, [kind]: value }))\n          return\n        }\n        const key = record.identity.id\n        void feedClientRef.current?.blob(ref).then((value) => {\n          if (selectedRef.current !== key) return\n          setRaw((current) => ({ ...current, [kind]: value }))\n        }).catch((error: unknown) => console.warn('[dsh-cache-bricks] raw read failed', error))\n      }}\n      {...(feed === undefined ? {} : { store: feed.store })}\n    />\n    </>\n  )\n}\n\n/**\n * Follow the host feed for a session.\n *\n * Absent or failing, it returns undefined and the board falls back to the\n * client's own fold — the collector is an enhancement, never a requirement.\n */\nfunction useFeed(sessionId: string | undefined): BrickFeed | undefined {\n  const [feed, setFeed] = useState<BrickFeed | undefined>(undefined)\n  useEffect(() => {\n    setFeed(undefined)\n    if (sessionId === undefined) return\n    const client = new BrickFeedClient()\n    feedClientRef.current = client\n    const stop = client.start(sessionId, (next) => { setFeed(next) })\n    return () => {\n      feedClientRef.current = undefined\n      stop()\n    }\n  }, [sessionId])\n  return feed\n}\n\n/** Map the client-side per-step fold onto the fallback brick source. */\nfunction readingsOf(turns: readonly CacheBricksNodeData[] | undefined): StepReading[] {\n  const readings: StepReading[] = []\n  for (const data of turns ?? []) {\n    for (const sample of data.steps) {\n      if (sample.usage === undefined) continue\n      const decided = badgeStatus({ usage: sample.usage, hasCacheEvidence: evidenceFor(sample) })\n      if (decided === null) continue\n      const ttft = ttftMs(sample.stepStartTime, sample.firstTokenTime)\n      readings.push({\n        turn: data.turn,\n        step: sample.step,\n        tone: decided.tone,\n        label: brickLabel(decided),\n        detail: decided.label.replace('Cache ', ''),\n        ended: data.ended,\n        ...(sample.provider === undefined ? {} : { provider: sample.provider }),\n        usage: sample.usage,\n        ...(typeof sample.usageTime === 'number' ? { usageAt: sample.usageTime } : {}),\n        ...(ttft > 0 ? { ttftMs: ttft } : {}),\n        ...(sample.seq === undefined ? {} : { seq: sample.seq }),\n      })\n    }\n  }\n  return readings\n}\n\n/**\n * Services required by the cache-bricks browser half.\n *\n * Only `slots` is a hard dependency (always present on the web surface). The\n * conversation-node registry — where a node Definition is registered — is\n * core-owned and its service key has changed across core versions (0.1.7\n * exposes `ctx.uiConversation.events`; legacy `ctx.conversationEvents` still\n * exists on other cores). It is resolved structurally with `ctx.get` instead\n * of being injected or read as a property: a loader entry is a sibling of the\n * core entry that provides the service, so property access without `inject`\n * throws `cannot get property \"<name>\" without inject` and would fail apply —\n * not degrade. `ctx.get` reads the global service store and returns\n * `undefined` when absent, so a missing or renamed registry disables only the\n * board, never pending or boot failure.\n */\nexport const inject = ['slots']\n\n/** The register-capable Definition registry surface the badge Definition needs. */\ninterface CacheBricksRegistry {\n  register(definition: unknown): () => void\n}\n\n/** Structural registry read across the two core service names. */\nfunction registerCacheBricksDefinition(\n  ctx: Context,\n  registerAt: (registry: CacheBricksRegistry) => void,\n): void {\n  const readService = (name: string): unknown => {\n    try {\n      return (ctx as unknown as { get(name: string): unknown }).get(name)\n    } catch {\n      return undefined\n    }\n  }\n  const asRegistry = (value: unknown): CacheBricksRegistry | undefined => {\n    if (value === null || typeof value !== 'object') return undefined\n    const node = value as { register?: (definition: unknown) => () => void; events?: unknown }\n    if (typeof node.register === 'function') return node as CacheBricksRegistry\n    const events = node.events\n    if (events !== null && typeof events === 'object') {\n      const eventsNode = events as { register?: (definition: unknown) => () => void }\n      if (typeof eventsNode.register === 'function') return eventsNode as CacheBricksRegistry\n    }\n    return undefined\n  }\n  const registry = asRegistry(readService('uiConversation'))\n    ?? asRegistry(readService('conversationEvents'))\n  if (registry === undefined) {\n    console.warn(\n      '[dsh-cache-bricks] conversation-node registry unavailable; the brick board is disabled. '\n      + 'Expected the registry on browser service uiConversation.events (or legacy conversationEvents).',\n    )\n    return\n  }\n  registerAt(registry)\n}\n\n/** Register the per-Turn reading and the brick board that paints it. */\nexport function apply(ctx: Context): void {\n  ctxRef.current = ctx\n  // Defer Definition registration until the chat-node seat is declared: that\n  // declaration lives under ui-chat, which injects `uiConversation`, so by the\n  // time this callback fires the registry is guaranteed ACTIVE and `ctx.get`\n  // resolves it. No renderer is registered for the kind: the node is published